/**
 * Reports are generated by the Flask API from Hive query results. API only.
 *
 * GET /reports/:type?format=csv|pdf&from&to&farm_id&batch_id → file download
 *     type: farm-performance | environmental | feed | growth | mortality | predictions
 * GET /reports?limit → { reports: [{ id, type, format, filters, generatedBy, createdAt, sizeBytes }] }
 */
import { api, downloadFromApi } from "./apiClient.js";
import { apiOnly } from "./dataSource.js";

export const REPORT_TYPES = [
  { id: "farm-performance", label: "Farm performance", icon: "warehouse", description: "Production, bird population and mortality per farm." },
  { id: "environmental", label: "Environmental", icon: "thermometer", description: "Temperature and humidity statistics and threshold breaches." },
  { id: "feed", label: "Feed consumption", icon: "wheat", description: "Daily and cumulative feed intake, feed per bird." },
  { id: "growth", label: "Growth", icon: "trending-up", description: "Average weight by age and growth rate per batch." },
  { id: "mortality", label: "Mortality", icon: "heart-pulse", description: "Daily deaths, mortality rate and trend per batch." },
  { id: "predictions", label: "Predictions", icon: "brain", description: "Model predictions with model name and timestamp. Decision support only." },
];

export const listReports = ({ limit = 10 } = {}) =>
  apiOnly(async () => (await api.get("/reports", { query: { limit } })).reports);

/** @returns {Promise<{blob: Blob, filename: string}>} */
export function downloadReport(type, { format, from, to, farmId, batchId }) {
  const fallback = `${type}-report-${from || "all"}-${to || "all"}.${format}`;
  return downloadFromApi(`/reports/${encodeURIComponent(type)}`, { format, from, to, farm_id: farmId, batch_id: batchId }, fallback);
}
